BEGIN;
PRAGMA writable_schema = on;
PRAGMA encoding = 'UTF-8';
PRAGMA page_size = '4096';
PRAGMA auto_vacuum = '0';
PRAGMA user_version = '0';
PRAGMA application_id = '0';
CREATE TABLE users (
	id VARCHAR(36) NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	hashed_password VARCHAR(255) NOT NULL, 
	display_name VARCHAR(120) NOT NULL, 
	timezone VARCHAR(64) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, username VARCHAR(30), username_changed_at TIMESTAMP, username_change_count INTEGER DEFAULT 0, is_admin BOOLEAN DEFAULT FALSE, 
	PRIMARY KEY (id)
);
CREATE TABLE content_embeddings (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	source_type VARCHAR(32) NOT NULL, 
	source_id VARCHAR(36) NOT NULL, 
	title VARCHAR(300) NOT NULL, 
	content TEXT NOT NULL, 
	route VARCHAR(200) NOT NULL, 
	embedding_json TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_embedding_source UNIQUE (user_id, source_type, source_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE calendar_events (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT, 
	starts_at DATETIME NOT NULL, 
	ends_at DATETIME, 
	all_day BOOLEAN NOT NULL, 
	category VARCHAR(32) NOT NULL, 
	recurrence VARCHAR(16) NOT NULL, 
	location VARCHAR(200), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, source_module VARCHAR(32), source_id VARCHAR(36), event_kind VARCHAR(16) DEFAULT 'normal', 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE career_profiles (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	resume_url VARCHAR(500), 
	github_username VARCHAR(120), 
	linkedin_url VARCHAR(500), 
	headline VARCHAR(200), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_career_profile_user UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE career_projects (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	description TEXT, 
	tech_stack VARCHAR(300), 
	url VARCHAR(500), 
	repo_url VARCHAR(500), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE job_applications (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	company VARCHAR(200) NOT NULL, 
	role VARCHAR(200) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	applied_at DATE, 
	interview_at DATE, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE finance_transactions (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	txn_type VARCHAR(16) NOT NULL, 
	amount FLOAT NOT NULL, 
	category VARCHAR(32) NOT NULL, 
	description VARCHAR(300), 
	txn_date DATE NOT NULL, 
	is_recurring BOOLEAN NOT NULL, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, expense_kind VARCHAR(8), recurring_id VARCHAR(36), loan_id VARCHAR(36), loan_emi_id VARCHAR(36), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE finance_budgets (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	category VARCHAR(32) NOT NULL, 
	monthly_limit FLOAT NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_finance_budget_category UNIQUE (user_id, category), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE goals (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT, 
	category VARCHAR(32) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	progress INTEGER NOT NULL, 
	notes TEXT, 
	target_date DATETIME, 
	parent_id VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	archived_at DATETIME, period VARCHAR(16) DEFAULT 'yearly', period_start DATE, period_end DATE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(parent_id) REFERENCES goals (id)
);
CREATE TABLE habits (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	description TEXT, 
	frequency VARCHAR(16) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE journal_entries (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	entry_date DATE NOT NULL, 
	entry_type VARCHAR(16) NOT NULL, 
	title VARCHAR(200), 
	content TEXT NOT NULL, 
	gratitude TEXT, 
	wins TEXT, 
	lessons TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_journal_entry UNIQUE (user_id, entry_date, entry_type), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE learning_items (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	item_type VARCHAR(32) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	provider VARCHAR(120), 
	url VARCHAR(500), 
	status VARCHAR(16) NOT NULL, 
	progress INTEGER NOT NULL, 
	target_date DATE, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, track_id VARCHAR(36), slug VARCHAR(64), sort_order INTEGER DEFAULT 0, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE runs (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	run_date DATE NOT NULL, 
	distance_km FLOAT NOT NULL, 
	duration_seconds INTEGER NOT NULL, 
	weather VARCHAR(64), 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, location VARCHAR(200), shoe VARCHAR(80), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE race_events (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	race_date DATE NOT NULL, 
	distance_type VARCHAR(32) NOT NULL, 
	distance_km FLOAT, 
	location VARCHAR(200), 
	registered BOOLEAN NOT NULL, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, organizer VARCHAR(200), bib_number VARCHAR(50), finish_time_seconds INTEGER, position INTEGER, medal BOOLEAN DEFAULT 0, certificate_url TEXT, photos TEXT, event_url TEXT, attended BOOLEAN DEFAULT 0, shoe VARCHAR(80), skipped BOOLEAN DEFAULT FALSE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE running_settings (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	weekly_goal_km FLOAT NOT NULL, 
	target_marathon_date DATE, 
	target_half_marathon_date DATE, 
	target_marathon_name VARCHAR(200), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_running_settings_user UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE wishlist_items (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT, 
	category VARCHAR(32) NOT NULL, 
	notes TEXT, 
	image_url VARCHAR(500), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, target_year INTEGER, achieved_date DATE, status VARCHAR(16) DEFAULT 'in_progress', priority VARCHAR(16) DEFAULT 'medium', photos TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE vocabulary_words (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	word VARCHAR(120) NOT NULL, 
	meaning TEXT NOT NULL, 
	examples TEXT, 
	pronunciation VARCHAR(120), 
	synonyms TEXT, 
	mastery INTEGER NOT NULL, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE writing_practices (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	content TEXT NOT NULL, 
	category VARCHAR(32) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE speaking_practices (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	prompt TEXT NOT NULL, 
	response TEXT, 
	category VARCHAR(32) NOT NULL, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE notifications (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	message TEXT NOT NULL, 
	module VARCHAR(32), 
	entity_id VARCHAR(36), 
	route VARCHAR(200), 
	is_read BOOLEAN NOT NULL, 
	channel VARCHAR(16) NOT NULL, 
	telegram_sent BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE life_milestones (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT, 
	milestone_date DATE NOT NULL, 
	photo_file_ids TEXT, 
	tags VARCHAR(300), 
	ai_generated BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE ai_memory_items (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	memory_key VARCHAR(120) NOT NULL, 
	memory_value TEXT NOT NULL, 
	category VARCHAR(32) NOT NULL, 
	importance INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE ocr_documents (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	file_id VARCHAR(36), 
	filename VARCHAR(255) NOT NULL, 
	doc_type VARCHAR(32) NOT NULL, 
	extracted_text TEXT, 
	status VARCHAR(16) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE voice_notes (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200), 
	transcript TEXT NOT NULL, 
	note_type VARCHAR(16) NOT NULL, 
	audio_file_id VARCHAR(36), 
	command_result TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE integration_connections (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	provider VARCHAR(32) NOT NULL, 
	display_name VARCHAR(120) NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	config_json TEXT, 
	status VARCHAR(16) NOT NULL, 
	last_sync_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, last_digest_at TIMESTAMP, webhook_secret VARCHAR(64), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE automation_rules (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	trigger_type VARCHAR(32) NOT NULL, 
	condition_json TEXT, 
	action_type VARCHAR(32) NOT NULL, 
	action_config_json TEXT, 
	enabled BOOLEAN NOT NULL, 
	last_run_at DATETIME, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE goal_milestones (
	id VARCHAR(36) NOT NULL, 
	goal_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	completed BOOLEAN NOT NULL, 
	sort_order INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	completed_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(goal_id) REFERENCES goals (id) ON DELETE CASCADE
);
CREATE TABLE habit_logs (
	id VARCHAR(36) NOT NULL, 
	habit_id VARCHAR(36) NOT NULL, 
	log_date DATE NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_habit_log_date UNIQUE (habit_id, log_date), 
	FOREIGN KEY(habit_id) REFERENCES habits (id) ON DELETE CASCADE
);
CREATE TABLE qa_entries (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	question TEXT NOT NULL, 
	current_answer TEXT NOT NULL, 
	tags_json TEXT NOT NULL, 
	linked_goal_id VARCHAR(36), 
	linked_journal_id VARCHAR(36), 
	ai_summary TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, type VARCHAR(64), is_deep_personal BOOLEAN DEFAULT FALSE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(linked_goal_id) REFERENCES goals (id), 
	FOREIGN KEY(linked_journal_id) REFERENCES journal_entries (id)
);
CREATE TABLE tasks (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT, 
	status VARCHAR(16) NOT NULL, 
	priority VARCHAR(16) NOT NULL, 
	category VARCHAR(64), 
	tags_json TEXT NOT NULL, 
	due_date DATETIME, 
	parent_id VARCHAR(36), 
	goal_id VARCHAR(36), 
	recurrence VARCHAR(16) NOT NULL, 
	completed_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, deleted_at TIMESTAMP, archived_at TIMESTAMP, version INTEGER DEFAULT 1, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(parent_id) REFERENCES tasks (id), 
	FOREIGN KEY(goal_id) REFERENCES goals (id)
);
CREATE TABLE qa_versions (
	id VARCHAR(36) NOT NULL, 
	entry_id VARCHAR(36) NOT NULL, 
	version_number INTEGER NOT NULL, 
	answer TEXT NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(entry_id) REFERENCES qa_entries (id) ON DELETE CASCADE
);
CREATE TABLE qa_types (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(64) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_qa_types_user_name UNIQUE (user_id, name), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE knowledge_subjects (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT, 
	icon VARCHAR(16), 
	order_index INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE knowledge_chapters (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	subject_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	order_index INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, closed_at TIMESTAMP, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(subject_id) REFERENCES knowledge_subjects (id) ON DELETE CASCADE
);
CREATE TABLE knowledge_sections (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	chapter_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	content TEXT NOT NULL, 
	order_index INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, archived_at TIMESTAMP, closed_at TIMESTAMP, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(chapter_id) REFERENCES knowledge_chapters (id) ON DELETE CASCADE
);
CREATE TABLE pending_notifications (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	channel VARCHAR(32) NOT NULL, 
	text TEXT NOT NULL, 
	parse_mode VARCHAR(16) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	attempts INTEGER NOT NULL, 
	max_attempts INTEGER NOT NULL, 
	last_error TEXT, 
	created_at DATETIME NOT NULL, 
	sent_at DATETIME, reply_markup_json TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE routines (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	description TEXT, 
	days_of_week_json TEXT NOT NULL, 
	timezone VARCHAR(64) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, start_date DATE, end_date DATE, skip_dates_json TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE routine_blocks (
	id VARCHAR(36) NOT NULL, 
	routine_id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	start_time TIME NOT NULL, 
	end_time TIME NOT NULL, 
	area VARCHAR(32) NOT NULL, 
	category VARCHAR(32) NOT NULL, 
	notes TEXT, 
	sort_order INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(routine_id) REFERENCES routines (id) ON DELETE CASCADE
);
CREATE TABLE running_shoes (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_running_shoes_user_name UNIQUE (user_id, name), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE user_preferences (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	"key" VARCHAR(64) NOT NULL, 
	value_json TEXT NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_user_preferences_user_key UNIQUE (user_id, "key"), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE goal_categories (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(32) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_goal_categories_user_name UNIQUE (user_id, name), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE wishlist_categories (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(32) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_wishlist_categories_user_name UNIQUE (user_id, name), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE routine_block_habits (
	block_id VARCHAR(36) NOT NULL, 
	habit_id VARCHAR(36) NOT NULL, 
	PRIMARY KEY (block_id, habit_id), 
	FOREIGN KEY(block_id) REFERENCES routine_blocks (id) ON DELETE CASCADE, 
	FOREIGN KEY(habit_id) REFERENCES habits (id) ON DELETE CASCADE
);
CREATE TABLE scheduled_report_runs (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	connection_id VARCHAR(36), 
	job_type VARCHAR(32) NOT NULL, 
	job_id VARCHAR(80) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	skip_reason VARCHAR(64), 
	error TEXT, 
	sections_json TEXT, 
	dedupe_key VARCHAR(191), 
	message_chars INTEGER, 
	scheduled_for DATETIME, 
	started_at DATETIME NOT NULL, 
	finished_at DATETIME, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_scheduled_report_runs_dedupe_key UNIQUE (dedupe_key), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	UNIQUE (dedupe_key)
);
CREATE TABLE username_history (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	old_username VARCHAR(30) NOT NULL, 
	new_username VARCHAR(30) NOT NULL, 
	changed_at DATETIME NOT NULL, 
	changed_by VARCHAR(36) NOT NULL, 
	reason TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE task_assignments (
	id VARCHAR(36) NOT NULL, 
	task_id VARCHAR(36) NOT NULL, 
	assignee_user_id VARCHAR(36) NOT NULL, 
	assigned_by_user_id VARCHAR(36) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	reason TEXT, 
	assigned_at DATETIME NOT NULL, 
	accepted_at DATETIME, 
	rejected_at DATETIME, 
	cancelled_at DATETIME, 
	completed_at DATETIME, 
	superseded_by_id VARCHAR(36), 
	PRIMARY KEY (id), 
	FOREIGN KEY(task_id) REFERENCES tasks (id), 
	FOREIGN KEY(assignee_user_id) REFERENCES users (id), 
	FOREIGN KEY(assigned_by_user_id) REFERENCES users (id), 
	FOREIGN KEY(superseded_by_id) REFERENCES task_assignments (id)
);
CREATE TABLE notification_settings (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	telegram_chat_id VARCHAR(64), 
	telegram_enabled BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_notification_settings_user UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE file_records (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	filename VARCHAR(255) NOT NULL, 
	content_type VARCHAR(128) NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	storage_backend VARCHAR(16) NOT NULL, 
	storage_key VARCHAR(500) NOT NULL, 
	url VARCHAR(1000) NOT NULL, 
	module VARCHAR(64), 
	entity_id VARCHAR(36), 
	created_at DATETIME NOT NULL, checksum_sha256 VARCHAR(64), extension VARCHAR(16), visibility VARCHAR(16) DEFAULT 'private', deleted_at TIMESTAMP, updated_at TIMESTAMP, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE mood_entries (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	log_date DATE NOT NULL, 
	stress INTEGER NOT NULL, 
	confidence INTEGER NOT NULL, 
	motivation INTEGER NOT NULL, 
	happiness INTEGER NOT NULL, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_mood_log_date UNIQUE (user_id, log_date), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE task_status_history (
	id VARCHAR(36) NOT NULL, 
	task_id VARCHAR(36) NOT NULL, 
	from_status VARCHAR(16), 
	to_status VARCHAR(16) NOT NULL, 
	changed_by_user_id VARCHAR(36) NOT NULL, 
	reason TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(task_id) REFERENCES tasks (id), 
	FOREIGN KEY(changed_by_user_id) REFERENCES users (id)
);
CREATE TABLE task_activity_log (
	id VARCHAR(36) NOT NULL, 
	task_id VARCHAR(36) NOT NULL, 
	actor_user_id VARCHAR(36) NOT NULL, 
	action VARCHAR(32) NOT NULL, 
	field VARCHAR(64), 
	old_value TEXT, 
	new_value TEXT, 
	metadata_json TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(task_id) REFERENCES tasks (id), 
	FOREIGN KEY(actor_user_id) REFERENCES users (id)
);
CREATE TABLE task_watchers (
	id VARCHAR(36) NOT NULL, 
	task_id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_task_watchers_task_user UNIQUE (task_id, user_id), 
	FOREIGN KEY(task_id) REFERENCES tasks (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE task_notes (
	id VARCHAR(36) NOT NULL, 
	task_id VARCHAR(36) NOT NULL, 
	author_user_id VARCHAR(36) NOT NULL, 
	body TEXT NOT NULL, 
	deleted_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(task_id) REFERENCES tasks (id), 
	FOREIGN KEY(author_user_id) REFERENCES users (id)
);
CREATE TABLE task_tags (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(64) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_task_tags_user_name UNIQUE (user_id, name), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE task_tag_links (
	id VARCHAR(36) NOT NULL, 
	task_id VARCHAR(36) NOT NULL, 
	tag_id VARCHAR(36) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_task_tag_links_task_tag UNIQUE (task_id, tag_id), 
	FOREIGN KEY(task_id) REFERENCES tasks (id), 
	FOREIGN KEY(tag_id) REFERENCES task_tags (id)
);
CREATE TABLE learning_tracks (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	slug VARCHAR(64) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT, 
	status VARCHAR(16) NOT NULL, 
	start_date DATE, 
	target_date DATE, 
	weekly_hours_target INTEGER NOT NULL, 
	sort_order INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_learning_track_user_slug UNIQUE (user_id, slug), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE learning_concepts (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	item_id VARCHAR(36) NOT NULL, 
	slug VARCHAR(64) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	summary TEXT, 
	week_number INTEGER, 
	estimated_minutes INTEGER, 
	sort_order INTEGER NOT NULL, 
	confidence INTEGER NOT NULL, 
	can_explain BOOLEAN NOT NULL, 
	failure_modes_known BOOLEAN NOT NULL, 
	tradeoffs_known BOOLEAN NOT NULL, 
	artifact_url VARCHAR(500), 
	completed_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_learning_concept_item_slug UNIQUE (item_id, slug), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(item_id) REFERENCES learning_items (id) ON DELETE CASCADE
);
CREATE TABLE learning_resources (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	item_id VARCHAR(36), 
	concept_id VARCHAR(36), 
	resource_type VARCHAR(32) NOT NULL, 
	title VARCHAR(300) NOT NULL, 
	url VARCHAR(1000) NOT NULL, 
	provider VARCHAR(120), 
	author VARCHAR(120), 
	duration_minutes INTEGER, 
	priority VARCHAR(16) NOT NULL, 
	sort_order INTEGER NOT NULL, 
	is_consumed BOOLEAN NOT NULL, 
	notes TEXT, 
	last_verified_at DATE, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(item_id) REFERENCES learning_items (id) ON DELETE CASCADE, 
	FOREIGN KEY(concept_id) REFERENCES learning_concepts (id) ON DELETE CASCADE
);
CREATE TABLE study_sessions (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	item_id VARCHAR(36) NOT NULL, 
	concept_id VARCHAR(36), 
	session_date DATE NOT NULL, 
	minutes INTEGER NOT NULL, 
	confidence INTEGER NOT NULL, 
	can_explain BOOLEAN NOT NULL, 
	artifact_url VARCHAR(500), 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(item_id) REFERENCES learning_items (id) ON DELETE CASCADE, 
	FOREIGN KEY(concept_id) REFERENCES learning_concepts (id) ON DELETE SET NULL
);
CREATE TABLE learning_concept_notes (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	concept_id VARCHAR(36) NOT NULL, 
	section_id VARCHAR(36) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_learning_concept_note UNIQUE (concept_id, section_id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(concept_id) REFERENCES learning_concepts (id) ON DELETE CASCADE, 
	FOREIGN KEY(section_id) REFERENCES knowledge_sections (id) ON DELETE CASCADE
);
CREATE TABLE routine_areas (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(32) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_routine_areas_user_name UNIQUE (user_id, name), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE routine_categories (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(32) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_routine_categories_user_name UNIQUE (user_id, name), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE github_sync_state (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	section_id VARCHAR(36) NOT NULL, 
	md_path VARCHAR(500) NOT NULL, 
	md_sha VARCHAR(64), 
	content_hash VARCHAR(64), 
	assets_json TEXT, 
	synced_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, remote_commit_sha VARCHAR(64), sync_status VARCHAR(16) DEFAULT 'never_synced', last_error TEXT, source_hash VARCHAR(64), 
	PRIMARY KEY (id), 
	CONSTRAINT uq_github_sync_user_section UNIQUE (user_id, section_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE finance_categories (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	txn_type VARCHAR(16) NOT NULL, 
	name VARCHAR(32) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_finance_category_user_type_name UNIQUE (user_id, txn_type, name), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE finance_recurring (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	txn_type VARCHAR(16) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	amount FLOAT NOT NULL, 
	expense_kind VARCHAR(8) NOT NULL, 
	category VARCHAR(32) NOT NULL, 
	frequency VARCHAR(16) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE, 
	day_of_month INTEGER NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE finance_loans (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	lender VARCHAR(200), 
	principal_amount FLOAT NOT NULL, 
	emi_amount FLOAT NOT NULL, 
	interest_rate FLOAT, 
	start_date DATE NOT NULL, 
	emi_start_date DATE NOT NULL, 
	tenure_months INTEGER NOT NULL, 
	emi_day INTEGER NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	notes TEXT, 
	closed_at DATE, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, foreclosure_amount FLOAT, foreclosure_notes TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE ai_use_case_model_selections (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	use_case VARCHAR(80) NOT NULL, 
	provider VARCHAR(32) NOT NULL, 
	model VARCHAR(80) NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_ai_use_case_selection UNIQUE (user_id, use_case), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE ai_use_case_model_selection_history (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	use_case VARCHAR(80) NOT NULL, 
	provider VARCHAR(32) NOT NULL, 
	model VARCHAR(80) NOT NULL, 
	effective_from DATETIME NOT NULL, 
	effective_to DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE writing_evaluations (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	writing_id VARCHAR(36) NOT NULL, 
	evaluation_key VARCHAR(64) NOT NULL, 
	provider VARCHAR(32) NOT NULL, 
	model VARCHAR(80) NOT NULL, 
	model_version VARCHAR(40), 
	prompt_version VARCHAR(40) NOT NULL, 
	rubric_version VARCHAR(40) NOT NULL, 
	evaluation_version VARCHAR(20) NOT NULL, 
	overall_score INTEGER NOT NULL, 
	dimensions_json TEXT NOT NULL, 
	strengths_json TEXT NOT NULL, 
	issues_json TEXT NOT NULL, 
	suggestions_json TEXT NOT NULL, 
	metrics_json TEXT NOT NULL, 
	already_strong BOOLEAN NOT NULL, 
	truncated BOOLEAN NOT NULL, 
	truncation_note TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_writing_evaluation_key UNIQUE (writing_id, evaluation_key), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(writing_id) REFERENCES writing_practices (id)
);
CREATE TABLE writing_rewrite_previews (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	writing_id VARCHAR(36) NOT NULL, 
	rewrite_key VARCHAR(64) NOT NULL, 
	provider VARCHAR(32) NOT NULL, 
	model VARCHAR(80) NOT NULL, 
	prompt_version VARCHAR(40) NOT NULL, 
	suggested_text TEXT NOT NULL, 
	why_better_json TEXT NOT NULL, 
	key_changes_json TEXT NOT NULL, 
	truncated BOOLEAN NOT NULL, 
	truncation_note TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_writing_rewrite_key UNIQUE (writing_id, rewrite_key), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(writing_id) REFERENCES writing_practices (id)
);
CREATE TABLE writing_ai_runs (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	writing_id VARCHAR(36), 
	provider VARCHAR(32) NOT NULL, 
	model VARCHAR(80) NOT NULL, 
	operation VARCHAR(40) NOT NULL, 
	prompt_version VARCHAR(40), 
	rubric_version VARCHAR(40), 
	status VARCHAR(20) NOT NULL, 
	latency_ms INTEGER, 
	prompt_tokens INTEGER, 
	completion_tokens INTEGER, 
	error_code VARCHAR(40), 
	error_message TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(writing_id) REFERENCES writing_practices (id)
);
CREATE TABLE finance_recurring_runs (
	id VARCHAR(36) NOT NULL, 
	recurring_id VARCHAR(36) NOT NULL, 
	period VARCHAR(7) NOT NULL, 
	expense_id VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_finance_recurring_run_period UNIQUE (recurring_id, period), 
	FOREIGN KEY(recurring_id) REFERENCES finance_recurring (id) ON DELETE CASCADE
);
CREATE TABLE finance_loan_emis (
	id VARCHAR(36) NOT NULL, 
	loan_id VARCHAR(36) NOT NULL, 
	emi_number INTEGER NOT NULL, 
	due_date DATE NOT NULL, 
	amount FLOAT NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	paid_date DATE, 
	expense_id VARCHAR(36), 
	expense_generated BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_finance_loan_emi_number UNIQUE (loan_id, emi_number), 
	FOREIGN KEY(loan_id) REFERENCES finance_loans (id) ON DELETE CASCADE
);
CREATE TABLE finance_loan_part_payments (
	id VARCHAR(36) NOT NULL, 
	loan_id VARCHAR(36) NOT NULL, 
	payment_date DATE NOT NULL, 
	amount FLOAT NOT NULL, 
	notes TEXT, 
	impact VARCHAR(16) NOT NULL, 
	resulting_emi_amount FLOAT, 
	resulting_tenure_months INTEGER, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(loan_id) REFERENCES finance_loans (id) ON DELETE CASCADE
);
